package th.co.scgroup1989.scpda;
import org.json.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.spec.*;import java.net.*;import java.io.*;import java.util.*;
// Shipping update client against explicit loopback API and a synthetic EC device.
public final class AppCenterProofHarness {
 public static void main(String[] args)throws Exception{
  if(args.length!=2||!args[0].matches("http://127\\.0\\.0\\.1:[0-9]+"))throw new Exception("Explicit isolated fixture required");final JSONObject fixture=new JSONObject(new String(Files.readAllBytes(Paths.get(args[1])),StandardCharsets.UTF_8));final PrivateKey key=KeyFactory.getInstance("EC").generatePrivate(new PKCS8EncodedKeySpec(Base64.getDecoder().decode(fixture.getString("privateKey"))));
  StockDaySession.DeviceProof device=new StockDaySession.DeviceProof(){public String publicKey(){return fixture.optString("publicKey");}public String deviceId(){return fixture.optString("deviceId");}public String certificate(){return fixture.optString("certificate");}public void saveCertificate(String c){throw new UnsupportedOperationException();}public String sign(String value)throws Exception{Signature s=Signature.getInstance("SHA256withECDSA");s.initSign(key);s.update(value.getBytes(StandardCharsets.UTF_8));return Base64.getEncoder().encodeToString(s.sign());}};
  StockDaySession.Wire wire=(method,path,body,headers,jar)->{if(!headers.isEmpty())throw new Exception("Unexpected operator credentials");HttpURLConnection c=(HttpURLConnection)new URL(args[0]+path).openConnection();c.setConnectTimeout(3000);c.setReadTimeout(5000);c.setInstanceFollowRedirects(false);c.setRequestMethod(method);c.setRequestProperty("Content-Type","application/json");c.setDoOutput(true);try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}int code=c.getResponseCode();try(InputStream in=code>=400?c.getErrorStream():c.getInputStream()){return new StockDaySession.Reply(code,new JSONObject(new String(read(in),StandardCharsets.UTF_8)));}finally{c.disconnect();}};
  AppCenterClient client=new AppCenterClient(device,wire);JSONObject newer=client.check(1);JSONObject current=client.check(newer.getJSONObject("release").getInt("versionCode"));if(!newer.getBoolean("updateAvailable")||current.getBoolean("updateAvailable"))throw new Exception("Version decision wrong");String path=newer.getString("downloadPath");if(!AppCenterClient.validPath(path)||AppCenterClient.validPath("https://example.com/evil.apk"))throw new Exception("Download origin scope wrong");HttpURLConnection c=(HttpURLConnection)new URL(args[0]+path).openConnection();c.setInstanceFollowRedirects(false);byte[] bytes;try(InputStream in=c.getInputStream()){bytes=read(in);}finally{c.disconnect();}String actual=hex(MessageDigest.getInstance("SHA-256").digest(bytes));if(!actual.equals(newer.getJSONObject("release").getString("sha256")))throw new Exception("Downloaded bytes differ");System.out.println(new JSONObject().put("status","PASS").put("shippingClientDeviceProof",true).put("operatorCredentialsSent",false).put("newerVersionDetected",true).put("equalVersionDoesNotPrompt",true).put("fixedDownloadPath",true).put("downloadHashMatches",true).put("physicalAndroidAccepted",false));
 }
 private static byte[] read(InputStream in)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>16777216)throw new Exception("oversized fixture");out.write(b,0,n);}return out.toByteArray();}
 private static String hex(byte[] value){StringBuilder b=new StringBuilder();for(byte v:value)b.append(String.format(java.util.Locale.ROOT,"%02x",v&255));return b.toString();}
}
